# area: abstract_classes
# hypothesis: A subclass that leaves an abstract property unimplemented stays abstract, so instantiating it is rejected by checkers and raises TypeError at runtime, while ABC.register adds a runtime subclass relation that checkers do not model.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        pass


class Square(Shape):
    def area(self) -> int:
        return 4


class Tri(Shape):
    @property
    def sides(self) -> int:
        return 3


class Ghost:
    @property
    def sides(self) -> int:
        return 0


Shape.register(Ghost)


def describe(s: Shape) -> int:
    return s.sides


print(describe(Tri()))
print(isinstance(Ghost(), Shape))
t = Tri()
reveal_type(t.sides)
try:
    sq = Square()  # expect-error
    print(sq.area())
except TypeError as exc:
    print('TypeError:', exc)
